const body = $input.item.json.body || {};
const required = ['nombre', 'apellido', 'matricula_tipo', 'matricula_numero', 'email', 'firma_url'];
const faltantes = required.filter((campo) => !body[campo] || String(body[campo]).trim() === '');

if (faltantes.length > 0) {
  throw new Error(`Faltan campos obligatorios: ${faltantes.join(', ')}`);
}

const matricula_tipo = String(body.matricula_tipo).trim().toUpperCase();
const matricula_numero = String(body.matricula_numero).trim();
const matricula_2_tipo = body.matricula_2_tipo ? String(body.matricula_2_tipo).trim().toUpperCase() : null;
const matricula_2_numero = body.matricula_2_numero ? String(body.matricula_2_numero).trim() : null;

if (!['MN', 'MP'].includes(matricula_tipo)) {
  throw new Error('matricula_tipo debe ser MN o MP');
}
if (!/^[0-9]+$/.test(matricula_numero)) {
  throw new Error('matricula_numero debe contener solo dígitos');
}
if ((matricula_2_tipo === null) !== (matricula_2_numero === null)) {
  throw new Error('Matrícula 2 incompleta: hacen falta matricula_2_tipo y matricula_2_numero, o ninguno');
}
if (matricula_2_tipo !== null) {
  if (!['MN', 'MP'].includes(matricula_2_tipo)) {
    throw new Error('matricula_2_tipo debe ser MN o MP');
  }
  if (!/^[0-9]+$/.test(matricula_2_numero)) {
    throw new Error('matricula_2_numero debe contener solo dígitos');
  }
}

return {
  json: {
    nombre: String(body.nombre).trim(),
    apellido: String(body.apellido).trim(),
    matricula_tipo,
    matricula_numero,
    matricula_2_tipo,
    matricula_2_numero,
    email: String(body.email).trim().toLowerCase(),
    especialidad: body.especialidad ? String(body.especialidad).trim() : null,
    firma_url: String(body.firma_url).trim(),
    activo: true
  }
};

// 8.7d (2026-10-01) - limpieza de la firma reemplazada.
// Corre DESPUÉS de responderle al formulario: nada de esto afecta el alta.
// 'Buscar firma previa' leyó, antes del upsert, la firma_url que tenía la fila
// con la misma matrícula (la que el upsert pisa). Si es distinta de la nueva,
// queda como candidata a borrar; el nodo siguiente confirma que nadie la use.
// Ante cualquier duda (búsqueda fallida, upsert sin id, URL ajena al bucket)
// no devuelve nada y la rama termina sin borrar.
const safe = (fn) => { try { return fn(); } catch (e) { return undefined; } };
const PREFIJO = 'https://tuedigqvvkvgongpcnjx.supabase.co/storage/v1/object/public/firmas/';

const nueva = safe(() => $('Validar payload').first(0).json.firma_url);
const upsert = safe(() => $('Upsert Profesional').first(0).json);
const guardado = Boolean(upsert && !upsert.error && (upsert.id || (Array.isArray(upsert) && upsert[0] && upsert[0].id)));
const previa = safe(() => $('Buscar firma previa').first(0).json);
const filas = previa && !previa.error && previa.statusCode === 200 && Array.isArray(previa.body) ? previa.body : [];

if (!guardado || !nueva) return [];

const vistas = new Set();
return filas
  .map((fila) => fila && fila.firma_url)
  .filter((url) => typeof url === 'string' && url !== nueva && url.startsWith(PREFIJO))
  .map((url) => ({ firma_url_vieja: url, archivo: url.slice(PREFIJO.length) }))
  .filter((c) => /^[A-Za-z0-9._-]+$/.test(c.archivo) && !vistas.has(c.archivo) && vistas.add(c.archivo))
  .map((c) => ({ json: c }));

